    let mut bestlength: c_uint = 0 as c_uint;

    let cache_ptr = lmc_view.sublen.wrapping_add(
        (ZOPFLI_CACHE_LENGTH as size_t)
            .wrapping_mul(pos)
            .wrapping_mul(3 as size_t),
    );

